/* A 64-bit constant that takes three or four instructions to build is one load from the block's literal pool. */
static void emit_const_lit(A64Buf *b, int rd, uint64_t v)
{
    int parts = 0;
    for (int k = 0; k < 4; k++) parts += ((v >> (16 * k)) & 0xffff) != 0;
    static int off = -1; if (off < 0) off = getenv("OCERZ_NO_CONST_LIT") ? 1 : 0;
    if (parts < 3 || g_n_raslit >= RASLIT_MAX || off) { a64_mov_imm64(b, rd, v); return; }
    g_raslit[g_n_raslit].site = a64_label(b);
    g_raslit[g_n_raslit].retaddr = v;
    g_raslit[g_n_raslit].kind = 1;
    g_raslit[g_n_raslit].tcr = 0;
    g_raslit[g_n_raslit].rt = rd;
    g_n_raslit++;
    a64_emit32(b, 0x58000000u | (uint32_t)(rd & 31));
}
typedef struct { _Alignas(16) uint64_t rip; void *body; } JitPscEnt;
#define PSC_N 32
/* An entry's rip word carries its column's retire generation above the address
   (rip ^ gen), so retiring a block bumps its column's vm->psc_gen instead of
   searching every table: a canonical target only matches an entry filled in
   its column's current generation.  (A non-canonical one, which would fault on
   x86, could meet an older generation's entry.) */
#define PSC_GEN_SHIFT 48
_Static_assert(PSC_N == OCERZ_PSC_COLS, "a PSC column per retire generation");
#define PSC_EMPTY_RIP UINT64_MAX
static JitPscEnt *g_psc_pool;
static size_t g_psc_used, g_psc_cap;
static JitPscEnt **g_psc_tables;
static size_t g_n_psc_tables, g_cap_psc_tables;
static void tc_note(const uint32_t *at, int kind, int form, uint64_t arg)
{
    if (!g_tc_on || !g_tc_entry)
        return;
    if (g_tc_nrel >= TC_RELOC_MAX) { g_tc_bad = 1; return; }
    g_tc_rel[g_tc_nrel].off = (uint32_t)(at - g_tc_entry);
    g_tc_rel[g_tc_nrel].kind = (uint8_t)kind;
    g_tc_rel[g_tc_nrel].form = (uint8_t)form;
    g_tc_rel[g_tc_nrel].arg = arg;
    g_tc_nrel++;
}
static void tc_imm64(A64Buf *b, int rd, int kind, uint64_t arg, uint64_t value)
{
    if (!g_tc_on) {
        a64_mov_imm64(b, rd, value);
        return;
    }
    tc_note(b->p, kind, 0, arg);
    a64_movz(b, rd, (uint16_t)value, 0);
    a64_movk(b, rd, (uint16_t)(value >> 16), 1);
    a64_movk(b, rd, (uint16_t)(value >> 32), 2);
    a64_movk(b, rd, (uint16_t)(value >> 48), 3);
}
#define TC_DLOG_MAX 4096
#define TC_DBYTES_MAX (64u << 10)
static struct { uint64_t pc; uint32_t at; uint32_t len; } g_tc_dlog[TC_DLOG_MAX];
static uint8_t g_tc_dbytes[TC_DBYTES_MAX];
static int g_tc_ndlog;
static uint32_t g_tc_nbytes;
static int g_tc_dbar;
static int g_tc_rec;
static int g_tc_learned;
static int jit_decode(uint64_t pc, X86Insn *out, int mode32)
{
    const uint8_t *code = (const uint8_t *)ocerz_g2h(pc);
    int rc = ocerz_decode_mode(code, 15, pc, out, mode32);
    if (rc == OCERZ_OK && g_tc_rec) {
        int last = g_tc_ndlog - 1;
        if (last >= g_tc_dbar && g_tc_dlog[last].pc + g_tc_dlog[last].len == pc &&
            g_tc_dlog[last].at + g_tc_dlog[last].len == g_tc_nbytes && g_tc_nbytes + out->len <= TC_DBYTES_MAX) {
            memcpy(g_tc_dbytes + g_tc_nbytes, code, out->len);
            g_tc_dlog[last].len += out->len;
            g_tc_nbytes += out->len;
        } else if (g_tc_ndlog < TC_DLOG_MAX && g_tc_nbytes + out->len <= TC_DBYTES_MAX) {
            g_tc_dlog[g_tc_ndlog].pc = pc;
            g_tc_dlog[g_tc_ndlog].at = g_tc_nbytes;
            g_tc_dlog[g_tc_ndlog].len = out->len;
            memcpy(g_tc_dbytes + g_tc_nbytes, code, out->len);
            g_tc_ndlog++;
            g_tc_nbytes += out->len;
        } else {
            g_tc_bad = 1;
        }
    }
    return rc;
}
static uint64_t *g_tc_noload;
static size_t g_tc_noload_cap, g_tc_noload_n;
static int tc_noload_has(uint64_t key)
{
    if (!g_tc_noload_n)
        return 0;
    size_t i = (size_t)((key * 0x9e3779b97f4a7c15ull) >> 20) & (g_tc_noload_cap - 1);
    for (; g_tc_noload[i]; i = (i + 1) & (g_tc_noload_cap - 1))
        if (g_tc_noload[i] == key)
            return 1;
    return 0;
}
static void tc_noload_add(uint64_t key)
{
    if (!key || ocerz_tcache_mode() != OCERZ_TC_ON || tc_noload_has(key))
        return;
    if (2 * (g_tc_noload_n + 1) > g_tc_noload_cap) {
        size_t ncap = g_tc_noload_cap ? g_tc_noload_cap * 2 : 4096;
        uint64_t *nv = (uint64_t *)calloc(ncap, sizeof *nv);
        if (!nv)
            return;
        for (size_t k = 0; k < g_tc_noload_cap; k++) {
            uint64_t v = g_tc_noload[k];
            if (!v) continue;
            size_t i = (size_t)((v * 0x9e3779b97f4a7c15ull) >> 20) & (ncap - 1);
            while (nv[i]) i = (i + 1) & (ncap - 1);
            nv[i] = v;
        }
        free(g_tc_noload);
        g_tc_noload = nv;
        g_tc_noload_cap = ncap;
    }
    size_t i = (size_t)((key * 0x9e3779b97f4a7c15ull) >> 20) & (g_tc_noload_cap - 1);
    while (g_tc_noload[i]) i = (i + 1) & (g_tc_noload_cap - 1);
    g_tc_noload[i] = key;
    g_tc_noload_n++;
}
static JitPscEnt *psc_alloc(void)
{
    if (g_psc_used + PSC_N > g_psc_cap) {
        size_t bytes = (size_t)1 << 22;
        void *p = mmap(NULL, bytes, PROT_READ | PROT_WRITE, MAP_ANON | MAP_PRIVATE, -1, 0);
        if (p == MAP_FAILED) return NULL;
        g_psc_pool = (JitPscEnt *)p; g_psc_used = 0; g_psc_cap = bytes / sizeof(JitPscEnt);
    }
    JitPscEnt *t = &g_psc_pool[g_psc_used];
    g_psc_used += PSC_N;
    for (int k = 0; k < PSC_N; k++)
        t[k].rip = PSC_EMPTY_RIP;
    if (g_n_psc_tables == g_cap_psc_tables) {
        size_t ncap = g_cap_psc_tables ? g_cap_psc_tables * 2 : 1024;
        JitPscEnt **nv = (JitPscEnt **)realloc(g_psc_tables, ncap * sizeof *nv);
        if (nv) { g_psc_tables = nv; g_cap_psc_tables = ncap; }
    }
    if (g_n_psc_tables < g_cap_psc_tables) g_psc_tables[g_n_psc_tables++] = t;
    return t;
}
static void psc_clear_all(void)
{
    for (size_t i = 0; i < g_n_psc_tables; i++)
        for (int k = 0; k < PSC_N; k++) {
            __atomic_store_n(&g_psc_tables[i][k].rip, PSC_EMPTY_RIP, __ATOMIC_RELEASE);
            __atomic_store_n(&g_psc_tables[i][k].body, (void *)NULL, __ATOMIC_RELEASE);
        }
}
static void ***g_ras_cells;
static size_t g_n_ras_cells, g_cap_ras_cells;
static void ras_cell_register(void **cell)
{
    if (g_n_ras_cells == g_cap_ras_cells) {
        size_t ncap = g_cap_ras_cells ? g_cap_ras_cells * 2 : 1024;
        void ***nv = (void ***)realloc(g_ras_cells, ncap * sizeof *nv);
        if (!nv) return;
        g_ras_cells = nv; g_cap_ras_cells = ncap;
    }
    g_ras_cells[g_n_ras_cells++] = cell;
}

