        r.l0[i] = g_l0[i] < 0 ? 0xff : (uint8_t)((g_l0[i] - 4) | (g_l0_dbl[i] ? 0x10 : 0));
        r.yc[i] = g_yc[i] < 0 ? 0xff : (uint8_t)(g_yc[i] - 4);
