        g_l0[r] = g_l0_fixed_lane[r];
        g_l0_dbl[r] = g_l0_fixed_dbl[r];
        g_l0_owners[g_l0_fixed_lane[r] - 4] = (uint16_t)(1u << r);
        g_lane_used |= (uint16_t)(1u << (g_l0_fixed_lane[r] - 4));
