                a64_mov_reg(&b, 1, pr, gr);
                if (g_n_promo_real < PE_MAX)
                    g_promo_real[g_n_promo_real++] = (struct JitPromo){
                        (int32_t)i, g_promo_mate[i], (uint8_t)pr };
