                uint32_t *ok = a64_label(&b);
                a64_bcond(&b, A64_EQ, 0);
                a64_sub_imm(&b, 1, hs, hs, 8);
                a64_mov_imm64(&b, JT0, insn->rip);
                a64_str(&b, 8, JT0, 20, RIP_OFF);
